require_once __DIR__.'/design.php';require_once __DIR__.'/studio-formula.php';
function studioOutput(?array $config):?array {if(!$config)return null;foreach($config['pages'] as &$page)foreach($page['blocks'] as &$block){if(!$block['responsive'])$block['responsive']=(object)[];else foreach($block['responsive'] as &$style)if(!$style)$style=(object)[];}if(isset($config['siteDesign'])){foreach(['moduleSettings','palette','hero','header','texts','accountTexts','moduleLayouts'] as $key)if(isset($config['siteDesign'][$key])&&!$config['siteDesign'][$key])$config['siteDesign'][$key]=(object)[];if(is_array($config['siteDesign']['moduleLayouts']??null))foreach($config['siteDesign']['moduleLayouts'] as &$layout)if(isset($layout['fields'])&&!$layout['fields'])$layout['fields']=(object)[];}return $config;}
function studioCoreRoutes():array{return array_merge(['dashboard','reports','accounting','settings','services','audit_logs','staff','about','notifications'],array_column(uiCatalog()['modules'],'id'));}
function studioCoreSlots(string $route):array {if($route==='dashboard')return ['heading','hero','empty','clocks','kpis','costs','budget','recent','units','smart'];return in_array($route,array_column(uiCatalog()['modules'],'id'),true)?['heading','hints','content']:['page'];}
function studioCoreView(array $u,string $project,string $route):bool {if(in_array($route,['settings','about','notifications'],true)){$flags=json_decode($u['allowed_modules_json']??'{}',true)?:[];if(($flags[$route]??true)===false)return false;$s=Database::getConnection()->prepare('SELECT document FROM tenant_workspaces WHERE tenant_id=:t');$s->execute(['t'=>getTenantId($u)]);$w=json_decode($s->fetchColumn()?:'{}',true);return !in_array('view',$w['appSettings']['dashboardDesign']['moduleSettings'][$route]['disabledActions']??[],true);}if($route==='staff'&&!isCompanyOwner($u))return false;return hasProjectAccess($u,$project,$route,'view');}
function studioDesignToken($design):string{return hash('sha256',json_encode($design,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));}
function studioId($v):void{designString($v,80);if(!preg_match('/^[a-zA-Z][a-zA-Z0-9_-]{0,79}$/D',$v))designInvalid();}
function studioRoute($v):void{designString($v,80);if(!preg_match('/^custom_[a-zA-Z0-9_-]{1,60}$/D',$v))designInvalid();}
function studioStyle($s,bool $partial=false):void{$limits=['borderWidth'=>[0,8],'radius'=>[0,100],'padding'=>[0,120],'gap'=>[0,120],'fontSize'=>[8,100],'width'=>[0,2400],'height'=>[0,2400],'x'=>[0,2400],'y'=>[0,4000],'z'=>[0,100],'opacity'=>[0,100],'span'=>[1,12]];$keys=array_merge(array_keys($limits),['background','color','border','hidden','align','shadow','layout']);designObject($s,$keys);if(!$partial&&count($s)!==count($keys))designInvalid();foreach($s as $k=>$v){if(isset($limits[$k]))designNumber($v,...$limits[$k]);elseif(in_array($k,['background','color','border']))designColor($v);elseif($k==='hidden')designBoolean($v);elseif($k==='align')designEnum($v,['start','center','end']);elseif($k==='shadow')designEnum($v,['none','soft','strong']);else designEnum($v,['column','row','grid','free']);}}
function studioFields($fields):void{designList($fields,40);$ids=[];foreach($fields as $f){designObject($f,['key','label','type','required','formula','precision','options']);studioId($f['key']??'');if(!preg_match('/^[a-z][a-zA-Z0-9_]{0,39}$/D',$f['key'])||isset($ids[$f['key']]))designInvalid();$ids[$f['key']]=true;designLocal($f['label']??[]);designEnum($f['type']??'',['text','number','date','select','formula']);designBoolean($f['required']??null);designString($f['formula']??null,500);designNumber($f['precision']??-1,0,6);if(!is_int($f['precision']))designInvalid();designList($f['options']??null,50);foreach($f['options'] as $x)designString($x,200);}try{studioTrees($fields);}catch(InvalidArgumentException $e){jsonResponse(false,null,$e->getMessage(),400);}}
function validateStudio($c):void{designObject($c,['schema','business','navigation','homePage','tokens','pages','components','modules','grants','siteDesign']);if(isset($c['siteDesign']))validateDesign($c['siteDesign']);designEnum($c['schema']??0,[1]);designEnum($c['business']??'',['construction','retail','services','custom']);designEnum($c['navigation']??'',['combined','business']);designString($c['homePage']??null,80);designObject($c['tokens']??null,['accent','background','color','radius','fontSize']);foreach(['accent','background','color'] as $k)designColor($c['tokens'][$k]??null);designNumber($c['tokens']['radius']??-1,0,100);designNumber($c['tokens']['fontSize']??0,8,100);
 $kinds=['section','heading','text','button','image','form','table','metric','core'];$all=[];$modules=[];designList($c['modules']??null,30);designUniqueIds($c['modules']);foreach($c['modules'] as $m){designObject($m,['id','title','enabled','locked','fields']);studioRoute($m['id']);$all[$m['id']]=true;$modules[$m['id']]=$m;designLocal($m['title']??[]);designBoolean($m['enabled']??null);designBoolean($m['locked']??null);studioFields($m['fields']??null);}
 designList($c['components']??null,60);designUniqueIds($c['components']);$components=[];foreach($c['components'] as $v){designObject($v,['id','name','kind','text','style']);studioId($v['id']);designString($v['name']??null,100);designEnum($v['kind']??'',$kinds);if(in_array($v['kind'],['section','form','table','metric','core']))designInvalid();designLocal($v['text']??[]);studioStyle($v['style']??null);$components[$v['id']]=$v;}
 designList($c['pages']??null,60);designUniqueIds($c['pages']);$pages=array_column($c['pages'],null,'id');$bound=[];foreach($c['pages'] as $p){designObject($p,['route','id','title','enabled','layout','background','gap','padding','minHeight','blocks']);studioRoute($p['id']);$route=$p['route']??'';if($route!==''){designEnum($route,studioCoreRoutes());if(isset($bound[$route]))designInvalid();$bound[$route]=true;}if(isset($all[$p['id']]))designInvalid();$all[$p['id']]=true;designLocal($p['title']??[]);designBoolean($p['enabled']??null);designEnum($p['layout']??'',['column','row','grid','free']);designColor($p['background']??null);foreach(['gap'=>[0,120],'padding'=>[0,120],'minHeight'=>[100,4000]] as $k=>$r)designNumber($p[$k]??-1,...$r);designList($p['blocks']??null,100);designUniqueIds($p['blocks']);$blocks=array_column($p['blocks'],null,'id');foreach($p['blocks'] as $b){designObject($b,['id','parent','kind','text','source','field','url','action','target','component','locked','style','responsive']);studioId($b['id']);designString($b['parent']??null,80);designEnum($b['kind']??'',$kinds);designLocal($b['text']??[]);designBoolean($b['locked']??null);studioStyle($b['style']??null);designObject($b['responsive']??null,['desktop','tablet','mobile']);foreach($b['responsive'] as $style)studioStyle($style,true);foreach(['source','field','target','component'] as $key)designString($b[$key]??null,80);designString($b['url']??null,2000);if($b['url']!==''&&(!filter_var($b['url'],FILTER_VALIDATE_URL)||parse_url($b['url'],PHP_URL_SCHEME)!=='https'||parse_url($b['url'],PHP_URL_USER)!==null))designInvalid();designEnum($b['action']??'',['none','page','module','core','link','notice']);if($b['component']!==''&&(!isset($components[$b['component']])||$components[$b['component']]['kind']!==$b['kind']))designInvalid();if($b['kind']==='core'){$source=explode(':',$b['source']);if($route===''||count($source)!==2||$source[0]!==$route||!in_array($source[1],studioCoreSlots($route),true)||$b['field']!==''||$b['component']!=='')designInvalid();}elseif($b['source']!==''&&!isset($modules[$b['source']]))designInvalid();if($b['field']!==''&&(!isset($modules[$b['source']])||!in_array($b['field'],array_column($modules[$b['source']]['fields'],'key'))))designInvalid();if($b['action']==='page'&&!isset($pages[$b['target']]))designInvalid();if($b['action']==='module'&&!isset($modules[$b['target']]))designInvalid();if($b['action']==='core'&&!in_array($b['target'],['dashboard','projects','expenses','steel','concrete','contractors','suppliers','labor','assets','apartments','payments','budget','documents','reports','accounting','partners','investments','transfers','credits','settings','services','about']))designInvalid();$cur=$b;$seen=[$b['id']=>true];$depth=0;while($cur['parent']!==''){if(!isset($blocks[$cur['parent']])||isset($seen[$cur['parent']])||++$depth>8||$blocks[$cur['parent']]['kind']!=='section')designInvalid();$seen[$cur['parent']]=true;$cur=$blocks[$cur['parent']];}}
 }if($c['homePage']!==''&&(!isset($pages[$c['homePage']])||(($pages[$c['homePage']]['route']??'')!==''&&$pages[$c['homePage']]['route']!=='dashboard')))designInvalid();designList($c['grants']??null,1000);$grantKeys=[];foreach($c['grants'] as $g){designObject($g,['userId','projectId','moduleId','actions']);designString($g['userId']??null,36);designString($g['projectId']??null,80);if(!isset($all[$g['moduleId']??'']))designInvalid();$grantKey=$g['userId'].'|'.$g['projectId'].'|'.$g['moduleId'];if(isset($grantKeys[$grantKey]))designInvalid();$grantKeys[$grantKey]=true;designList($g['actions']??null,6);foreach($g['actions'] as $v)designEnum($v,['view','create','edit','delete','approve','export']);}if(strlen(json_encode($c))>1000000)designInvalid();}
function studioPermission(array $u,array $cfg,string $module,string $project,string $action):bool{if(isOffice7Owner($u))return true;$m=null;$coreRoute='';foreach($cfg['modules'] as $v)if($v['id']===$module)$m=$v;foreach($cfg['pages'] as $page)if($page['id']===$module){$m=['enabled'=>$page['enabled'],'locked'=>$action!=='view'];$coreRoute=$page['route']??'';}if($coreRoute!==''&&!studioCoreView($u,$project,$coreRoute))return false;if(!$m||!$m['enabled']||($m['locked']&&$action!=='view'))return false;$flags=json_decode($u['allowed_modules_json']??'{}',true)?:[];if(($flags[$module]??true)===false)return false;
 // Existing account restrictions still apply. Studio grants only expand its own custom modules.
 $s=Database::getConnection()->prepare('SELECT document FROM tenant_workspaces WHERE tenant_id=:t');$s->execute(['t'=>getTenantId($u)]);$w=json_decode($s->fetchColumn()?:'{}',true);$policy=$w['appSettings']['dashboardDesign']['moduleSettings'][$module]??[];if(($policy['locked']??false)&&$action!=='view'||in_array('view',$policy['disabledActions']??[])||in_array($action,$policy['disabledActions']??[]))return false;
  $matches=array_values(array_filter($cfg['grants'],fn($g)=>$g['userId']===$u['id']&&$g['moduleId']===$module));$specific=array_values(array_filter($matches,fn($g)=>$g['projectId']===$project));$applicable=$specific?:array_values(array_filter($matches,fn($g)=>$g['projectId']==='*'));if($applicable){foreach($applicable as $g)if(in_array('view',$g['actions'],true)&&in_array($action,$g['actions'],true))return true;return false;}return $coreRoute!==''?true:isCompanyOwner($u);}
